        }

        .subtitle {
            font-style: italic;
            color: #6b8e6b;
            margin-bottom: 20px;
            border-bottom: 1px dashed #a5bea5;
            padding-bottom: 8px;
            font-size: 15px;
        }

        .section {
            margin-bottom: 25px;
            position: relative;
            clear: both;
        }

        .section-title {
            font-family: 'Ma Shan Zheng', cursive;
            font-size: 20px;
            color: #435643;
            border-bottom: 1px solid #8b9a7d;
            padding-bottom: 5px;
            margin-bottom: 15px;
            display: inline-block;
        }

        .experience-item {
            margin-bottom: 18px;
            padding-left: 18px;
            border-left: 3px solid #8b9a7d;
            position: relative;
            transition: all 0.3s ease;
        }

        .experience-item:hover {
            border-left-color: #435643;
            background-color: rgba(139, 154, 125, 0.1);
            padding-top: 5px;
            padding-bottom: 5px;
            border-radius: 0 5px 5px 0;
        }

        .experience-title {
            font-weight: bold;
            color: #435643;
            margin-bottom: 8px;
            position: relative;
        }

        .experience-title:before {
            content: "✧";
            position: absolute;
            left: -22px;
            color: #6b8e6b;
        }

        .experience-description {
            line-height: 1.6;
            text-align: justify;
        }

        .footer {
            text-align: center;
            margin-top: 30px;
            font-style: italic;
            color: #6b8e6b;
            border-top: 1px solid #8b9a7d;
            padding-top: 15px;
            position: relative;
        }

        .footer:before {
            content: "❀";
            position: absolute;
            top: -10px;
            left: 50%;
            transform: translateX(-50%);
            background: #e8ede0;
            padding: 0 10px;
            color: #8b9a7d;
        }

        .watermark {
            position: fixed;
            bottom: 10px;
            right: 10px;
            font-size: 14px;
            color: #8b9a7d;
            opacity: 0.7;
            pointer-events: none;
            font-style: italic;
        }

        /* Scrollbar styling */
        .resume-container::-webkit-scrollbar {
            width: 8px;
        }

        .resume-container::-webkit-scrollbar-track {
            background: #e8ede0;
            border-radius: 10px;
        }

        .resume-container::-webkit-scrollbar-thumb {
            background-color: #8b9a7d;
            border-radius: 10px;
            border: 2px solid #e8ede0;
        }

        /* Corner decorations */
        .corner {
            position: absolute;
            width: 40px;
            height: 40px;
            opacity: 0.5;
        }

        .top-left {
            top: 10px;
            left: 10px;
            border-top: 3px solid #8b9a7d;
            border-left: 3px solid #8b9a7d;
        }

        .top-right {
            top: 10px;
            right: 10px;
            border-top: 3px solid #8b9a7d;
            border-right: 3px solid #8b9a7d;
        }

        .bottom-left {
            bottom: 10px;
            left: 10px;
            border-bottom: 3px solid #8b9a7d;
            border-left: 3px solid #8b9a7d;
        }

        .bottom-right {
            bottom: 10px;
            right: 10px;
            border-bottom: 3px solid #8b9a7d;
            border-right: 3px solid #8b9a7d;
        }
    </style>
